// TH14 v1.00b Extra (st07) wave th14_s7_w09.
// Source: st07.ecl.txt:844-858 MainSub05 (entry); GirlC02 400-422 and
// GirlC02_at 424-462 (dependency). Extra source gate: O bits only, target rank 4.

const TIME_LIMIT: int = 2724;
const OPENING_BUFFER: int = 120;

// MainSub05: $A=4, four create+wait(150) rounds, then one last pair.
async sub pattern() {
    wait(OPENING_BUFFER);
    for i in 0..4 {
        spawn_pair();
        wait(150);
    }
    spawn_pair();
}

sub spawn_pair() {
    // enmCreate(-224) is unmirrored; enmCreateM(+224) carries mirror=1, so the
    // right enemy flies mirrored while keeping its given spawn x.
    _ = spawn_enemy(-224fx, 128fx, 300, 0, 0, 0, girl_main(0));
    _ = spawn_enemy(224fx, 128fx, 300, 0, 0, 0, girl_main(1));
}

// GirlC02 400-422: setHurtbox(24,24)/setHitbox(16,16); moveVel(0,1.5);
// moveVelTime(80,1,-0.3926991,0.1); at spawn+60 start async attack;
// at spawn+260 moveVelTime(80,1,-0.7853982,1.0); then endless wait(1000) loop.
async sub girl_main(mir: int) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    if mir == 0 {
        move_vel(0, 0deg, 1.5fx, EASE_LINEAR);
        move_vel(80, -4096bam, 0.1fx, EASE_QUAD_IN);
    } else {
        // Mirror across x: angle a becomes 180deg-a.
        move_vel(0, 180deg, 1.5fx, EASE_LINEAR);
        move_vel(80, 36864bam, 0.1fx, EASE_QUAD_IN);
    }
    wait(60);
    spawn girl_attack();
    wait(200);
    if mir == 0 {
        move_vel(80, -8192bam, 1fx, EASE_QUAD_IN);
    } else {
        move_vel(80, 40960bam, 1fx, EASE_QUAD_IN);
    }
    loop { wait(1); }
}

// GirlC02_at 424-462: etSprite(0,5,13), aim mode 1, count 5/6 alternating,
// speed 4, angle = player angle +-30deg lanes, 10 radial-offset volleys per
// round, 5 rounds of wait(15), then wait(40); 180 rounds.
async sub girl_attack() {
    sh_reset(0);
    sh_sprite(0, TH14_BALL2, 13);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_speed(0, 4fx, 0fx);
    // ANIM a=1 birth retreat: position -= 4*velocity, i.e. -16px along each
    // bullet's own angle (birth animation itself is omitted by policy).
    sh_dist(0, -16fx);
    // %C = %RANDRAD (line 435) is unused by the source but still consumes a draw.
    var c: angle = rand(65536) as angle;
    for e in 0..180 {
        var d: int = 5;
        for f in 0..5 {
            // %ANGLE_PLAYER is read once per round, shared by all 10 volleys.
            var aim: angle = atan2($player_y - $self_y, $player_x - $self_x);
            sh_count(0, d, 1);
            d = 11 - d;
            // circlePos(%A,%B,%RANDRAD,%RANDF*16): random sample order kept.
            var a1: angle = rand(65536) as angle;
            var r1: fx = ((rand(65536) - 32768) as fx / 65536 + 0.5fx) * 16fx;
            sh_offset_abs(0, $self_x + r1 * cos(a1), $self_y + r1 * sin(a1));
            sh_angle(0, aim, 30deg);
            for g in 0..10 {
                // etOffsetRad(%RANDRAD,%RANDF*8) then etOn(0), ten times per round.
                var a2: angle = rand(65536) as angle;
                var r2: fx = ((rand(65536) - 32768) as fx / 65536 + 0.5fx) * 8fx;
                sh_offset_rad(0, a2, r2);
                sh_fire(0);
            }
            wait(15);
        }
        wait(40);
    }
}

// Independent invincible shell (TH18/TH14 validation appendix).
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
